{"operation":"run_python","code":"import mpmath
mpmath.mp.dps = 50

def O(n):
    return sum(1/(2*k-1) for k in range(1, n+1))

def O_bar(n):
    return sum((-1)**(k-1)/(2*k-1) for k in range(1, n+1))

def compute_S(N):
    s = mpmath.mpf('0')
    for n in range(1, N+1):
        s += (-1)**(n-1) * O(n) * O_bar(n) / n**2
    return s

print("S(1000) =", compute_S(1000))
print("S(5000) =", compute_S(5000))
print("S(10000) =", compute_S(10000))"}

{"operation":"run_python","code":"def dp_gamma(m, n):
    history = {} 
    for m0 in range(1<<m):
        history[(m0, 0)] = bin(m0).count('1') 

    for j in range(1, n):
        new_history = {}
        for (prev_mask, prev_prev_mask), w in history.items():
            for curr_mask in range(1<<m):
                ok = True
                for i in range(m):
                    neighbors_in_S = 0
                    if prev_prev_mask & (1<<i): neighbors_in_S += 1
                    if prev_mask & (1<<i): neighbors_in_S += 1
                    if curr_mask & (1<<i): neighbors_in_S += 1
                    if i > 0 and (prev_mask >> (i-1)) & 1: neighbors_in_S += 1
                    if i < m-1 and (prev_mask >> (i+1)) & 1: neighbors_in_S += 1
                    if neighbors_in_S < 2:
                        ok = False
                        break
                if ok:
                    new_w = w + bin(curr_mask).count('1')
                    key = (curr_mask, prev_mask)
                    if key not in new_history or new_w < new_history[key]:
                        new_history[key] = new_w
        history = new_history

    final_ans = 10**9
    for (prev_mask, prev_prev_mask), w in history.items():
        ok = True
        for i in range(m):
            neighbors_in_S = 0
            if prev_prev_mask & (1<<i): neighbors_in_S += 1
            if prev_mask & (1<<i): neighbors_in_S += 1
            if i > 0 and (prev_mask >> (i-1)) & 1: neighbors_in_S += 1
            if i < m-1 and (prev_mask >> (i+1)) & 1: neighbors_in_S += 1
            if neighbors_in_S < 2:
                ok = False
                break
        if ok:
            final_ans = min(final_ans, w)
    return final_ans

print("P3xP2:", dp_gamma(3, 2))
print("P3xP3:", dp_gamma(3, 3))
print("P3xP4:", dp_gamma(3, 4))
print("P3xP5:", dp_gamma(3, 5))
print("P3xP6:", dp_gamma(3, 6))
print("P3xP7:", dp_gamma(3, 7))
